<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { ApiClient } from '../api'; import { useSessionStore } from '../stores/session'; import type { Task } from '../types'; import StatusPill from '../components/StatusPill.vue'
const session=useSessionStore(),api=new ApiClient(()=>session.token),tasks=ref<Task[]>([]),note=ref('已完成合成教学记录，未发现新增信息。'); async function load(){tasks.value=await api.myTasks()} async function complete(task:Task){try{await api.updateTask(task.id,'COMPLETED',note.value);ElMessage.success('任务已完成并写入审计');await load()}catch(e:any){ElMessage.error(e.message)}} onMounted(()=>load().catch((e:any)=>ElMessage.error(e.message)))
</script>
<template><section class="workspace"><div class="page-heading"><div><span class="eyebrow">FOLLOW-UP OPERATIONS</span><h1>随访任务看板</h1><p>仅查看完成任务所需的最小信息，不显示内部 Prompt 或 Agent 推理过程。</p></div><div class="stat-card"><strong>{{tasks.filter(t=>t.status!=='COMPLETED').length}}</strong><span>待办任务</span></div></div><div class="panel"><div class="panel-title"><h2>我的任务</h2><span class="safe-chip">高血压教学模板 v1</span></div><div v-if="!tasks.length" class="empty large">暂无分配任务，请先由医务人员激活随访计划。</div><div class="task-board"><article v-for="task in tasks" :key="task.id" class="follow-card"><div class="task-icon">✓</div><div class="grow"><small>{{task.taskCode}}</small><h3>{{task.title}}</h3><p>截止 {{new Date(task.dueAt).toLocaleString()}}</p><el-input v-if="task.status!=='COMPLETED'" v-model="note" type="textarea" :rows="2" /></div><div class="task-action"><StatusPill :value="task.status"/><el-button v-if="task.status!=='COMPLETED'" type="primary" @click="complete(task)">完成任务</el-button></div></article></div></div></section></template>

